public class CsvProcessingService : BackgroundService
{
    private readonly Channel<CsvJob> _channel;
    private readonly ILogger<CsvProcessingService> _logger;

    public CsvProcessingService(ILogger<CsvProcessingService> logger)
    {
        _logger = logger;
        _channel = Channel.CreateUnbounded<CsvJob>();
    }

    public async Task EnqueueAsync(CsvJob job)
    {
        await _channel.Writer.WriteAsync(job);
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        await foreach (var job in _channel.Reader.ReadAllAsync(stoppingToken))
        {
            try
            {
                await ProcessCsvAsync(job, stoppingToken);
                job.ReportSuccess();
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to process job {JobId}", job.Id);
                job.ReportFailure();
            }
        }
    }
}

