// API - Producer
public class CsvController : ControllerBase
{
    private readonly IRabbitMQProducer _producer;

    [HttpPost]
    public IActionResult Upload(IFormFile file)
    {
        var message = new CsvUploadMessage { FileName = file.FileName };
        _producer.Publish(message, exchange: "jobs", routingKey: "csv.process");
        return Accepted();
    }
}

// Worker Service - Consumer
public class CsvWorker : BackgroundService
{
    private readonly IRabbitMQConsumer _consumer;

    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        await _consumer.Consume<CsvUploadMessage>(
            queue: "csv-jobs",
            onMessage: async msg => await ProcessCsvAsync(msg, ct));
    }
}
